/**
 * "Open in Google Colab" links for the coding lessons.
 *
 * Every coding lesson has a notebook in the public repository
 * github.com/wamugii/notebooks (generated by
 * wamugii-backend/scripts/course_make_notebooks.py). Colab opens a notebook
 * straight from GitHub, so one click gives the student the whole lesson,
 * ready to run, with a free GPU for the deep-learning lessons.
 *
 * Set VITE_COLAB_REPO ("owner/repo") to use another repository.
 */

const REPO = ((import.meta.env.VITE_COLAB_REPO as string | undefined) || 'wamugii/notebooks').replace(
  /^\/+|\/+$/g,
  '',
)

/** Courses whose lessons contain Python examples (and have notebooks). */
export const CODING_COURSES = new Set([
  'math-python-for-ai',
  'machine-learning-fundamentals',
  'deep-learning-neural-networks',
  'modern-ai-llms-generative',
  'responsible-ai-deployment',
])

/** Colab link for lesson `number` (its position in the course, from 1) of a coding course, else null. */
export function colabLessonUrl(courseSlug: string, number: number | null | undefined): string | null {
  if (!CODING_COURSES.has(courseSlug) || !number || number < 1) return null
  const file = `lesson-${String(number).padStart(2, '0')}.ipynb`
  return `https://colab.research.google.com/github/${REPO}/blob/main/${courseSlug}/${file}`
}
